export type Instruction =
  | { kind: "query"; name: string; arguments: string[] }
  | { kind: "command"; name: string; arguments: string[] };

export interface InstructionGroups {
  queries: Instruction[];
  commands: Instruction[];
}

export function splitInstructions(
  instructions: readonly Instruction[],
): InstructionGroups {
  const queries: Instruction[] = [];
  const commands: Instruction[] = [];

  for (const instruction of instructions) {
    const clone: Instruction = { ...instruction, arguments: instruction.arguments };
    if (clone.kind === "query") {
      queries.push(clone);
    } else {
      commands.push(clone);
    }
  }
  return { queries, commands };
}
```

