import { Instruction, splitInstructions } from "./solution";

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
}
function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

deepEqual(splitInstructions([]), { queries: [], commands: [] }, "empty input");

const sharedArguments = ["shared"];
const instructions: Instruction[] = [
  { kind: "command", name: "deploy", arguments: ["prod", "fast"] },
  { kind: "query", name: "status", arguments: sharedArguments },
  { kind: "command", name: "restart", arguments: [] },
  { kind: "query", name: "logs", arguments: sharedArguments },
];
const before = JSON.stringify(instructions);
const groups = splitInstructions(instructions);
deepEqual(groups.queries.map((item) => item.name), ["status", "logs"], "query relative order");
deepEqual(groups.commands.map((item) => item.name), ["deploy", "restart"], "command relative order");
deepEqual(groups.queries.map((item) => item.arguments), [["shared"], ["shared"]], "query arguments copied");
deepEqual(groups.commands.map((item) => item.arguments), [["prod", "fast"], []], "command arguments copied");
deepEqual(JSON.stringify(instructions), before, "input remains unchanged");

assert(groups.commands[0] !== instructions[0], "command object detached from input");
assert(groups.commands[0].arguments !== instructions[0].arguments, "command arguments detached from input");
assert(groups.queries[0] !== instructions[1], "query object detached from input");
assert(groups.queries[0].arguments !== sharedArguments, "query arguments detached from shared input");
assert(groups.queries[0].arguments !== groups.queries[1].arguments, "returned argument arrays do not alias each other");

groups.commands[0].name = "changed";
groups.commands[0].arguments[0] = "changed";
groups.queries[0].arguments.push("new");
deepEqual(instructions, [
  { kind: "command", name: "deploy", arguments: ["prod", "fast"] },
  { kind: "query", name: "status", arguments: ["shared"] },
  { kind: "command", name: "restart", arguments: [] },
  { kind: "query", name: "logs", arguments: ["shared"] },
], "returned mutations cannot reach input");
deepEqual(groups.queries[1].arguments, ["shared"], "returned mutations cannot cross aliases");

const second = splitInstructions(instructions);
assert(second.queries !== groups.queries && second.commands !== groups.commands, "calls return new group arrays");
deepEqual(second.queries.map((item) => item.name), ["status", "logs"], "later call unaffected by prior result mutation");

